const PAGE_SCRIPTS = "// Filter functionality for opportunities page\n  document.addEventListener('DOMContentLoaded', () => {\n    // Bookmark toggle\n    const favoriteButtons = document.querySelectorAll('button[title=\"Luu tin tuyen dung\"]');\n    favoriteButtons.forEach(btn => {\n      btn.addEventListener('click', (e) => {\n        e.preventDefault();\n        const icon = btn.querySelector('.material-symbols-outlined');\n        if (icon) {\n          const isFilled = icon.style.fontVariationSettings && icon.style.fontVariationSettings.includes(\"'FILL' 1\");\n          if (isFilled) {\n            icon.style.fontVariationSettings = \"'FILL' 0\";\n            btn.classList.remove('text-error', 'border-error');\n            btn.classList.add('text-outline');\n          } else {\n            icon.style.fontVariationSettings = \"'FILL' 1\";\n            btn.classList.add('text-error', 'border-error');\n            btn.classList.remove('text-outline');\n          }\n        }\n      });\n    });\n\n    // Parse job cards\n    const cards = Array.from(document.querySelectorAll('article.group'));\n    cards.forEach(card => {\n      const text = card.textContent || '';\n      const salaryMatch = text.match(/(\\d{1,3}(?:\\.\\d{3})*)\\s*-\\s*(\\d{1,3}(?:\\.\\d{3})*)\\s*VND/);\n      if (salaryMatch) {\n        card.setAttribute('data-sal-min', salaryMatch[1].replace(/\\./g, ''));\n        card.setAttribute('data-sal-max', salaryMatch[2].replace(/\\./g, ''));\n      } else if (text.indexOf('Thuong luong') >= 0 || text.indexOf('Thuong lu?ng') >= 0) {\n        card.setAttribute('data-sal-neg', '1');\n      }\n      if (text.indexOf('Hybrid') >= 0) card.setAttribute('data-wt', 'hybrid');\n      else if (text.indexOf('Remote') >= 0) card.setAttribute('data-wt', 'remote');\n      else if (text.indexOf('To�n th?i gian') >= 0 || text.indexOf('Toan thoi gian') >= 0) card.setAttribute('data-wt', 'fulltime');\n      else if (text.indexOf('B�n th?i gian') >= 0 || text.indexOf('Ban thoi gian') >= 0) card.setAttribute('data-wt', 'parttime');\n    });\n\n    function getActiveSalary() {\n      const checked = document.querySelector('input[name=\"salary\"]:checked');\n      if (!checked) return 'all';\n      const label = (checked.parentElement && checked.parentElement.textContent || '').trim();\n      if (label.indexOf('Du?i 15') >= 0 || label.indexOf('Duoi 15') >= 0) return 'under15';\n      if (label.indexOf('15') >= 0 && label.indexOf('30') >= 0) return '15-30';\n      if (label.indexOf('30') >= 0 && label.indexOf('50') >= 0) return '30-50';\n      if (label.indexOf('Tr�n 50') >= 0 || label.indexOf('Tren 50') >= 0) return 'above50';\n      if (label.indexOf('Thuong lu?ng') >= 0 || label.indexOf('Thuong luong') >= 0) return 'negotiable';\n      return 'all';\n    }\n\n    function getActiveWorkTypes() {\n      const checkboxes = document.querySelectorAll('input[type=\"checkbox\"]');\n      const types = [];\n      checkboxes.forEach(cb => {\n        if (cb.checked) {\n          const label = (cb.parentElement && cb.parentElement.textContent || '').trim();\n          if (label.indexOf('To�n th?i gian') >= 0 || label.indexOf('Toan thoi gian') >= 0) types.push('fulltime');\n          if (label.indexOf('B�n th?i gian') >= 0 || label.indexOf('Ban thoi gian') >= 0) types.push('parttime');\n          if (label.indexOf('Hybrid') >= 0) types.push('hybrid');\n          if (label.indexOf('Remote') >= 0) types.push('remote');\n        }\n      });\n      return types;\n    }\n\n    function applyFilters() {\n      const salaryFilter = getActiveSalary();\n      const workTypes = getActiveWorkTypes();\n      const hasWorkTypeFilter = workTypes.length > 0 && workTypes.length < 4;\n\n      cards.forEach(card => {\n        let show = true;\n        if (salaryFilter !== 'all') {\n          const isNeg = card.getAttribute('data-sal-neg') === '1';\n          if (salaryFilter === 'negotiable') {\n            if (!isNeg) show = false;\n          } else if (isNeg) {\n            show = false;\n          } else {\n            const min = parseInt(card.getAttribute('data-sal-min') || '0');\n            const max = parseInt(card.getAttribute('data-sal-max') || '0');\n            const avg = (min + max) / 2;\n            if (salaryFilter === 'under15' && avg >= 15000000) show = false;\n            if (salaryFilter === '15-30' && (avg < 15000000 || avg >= 30000000)) show = false;\n            if (salaryFilter === '30-50' && (avg < 30000000 || avg >= 50000000)) show = false;\n            if (salaryFilter === 'above50' && avg < 50000000) show = false;\n          }\n        }\n        if (hasWorkTypeFilter) {\n          const cardWt = card.getAttribute('data-wt');\n          if (workTypes.indexOf(cardWt) < 0) show = false;\n        }\n        card.style.display = show ? '' : 'none';\n      });\n\n      const visible = cards.filter(c => c.style.display !== 'none').length;\n      const counter = document.querySelector('.font-headline-sm.text-headline-sm.text-on-surface.font-bold');\n      if (counter) counter.textContent = 'T�m th?y ' + visible + ' vi?c l�m ph� h?p';\n    }\n\n    document.querySelectorAll('input[name=\"salary\"]').forEach(input => {\n      input.addEventListener('change', applyFilters);\n    });\n    document.querySelectorAll('input[type=\"checkbox\"]').forEach(input => {\n      input.addEventListener('change', applyFilters);\n    });\n\n    // Sort dropdown\n    const sortSelect = document.querySelector('select');\n    if (sortSelect) {\n      sortSelect.addEventListener('change', () => {\n        const grid = document.querySelector('.grid.grid-cols-1.xl\\\\:grid-cols-2');\n        if (!grid) return;\n        const sortedCards = Array.from(grid.querySelectorAll('article.group'));\n        const val = sortSelect.value;\n        sortedCards.sort((a, b) => {\n          if (val.indexOf('Luong cao') >= 0 || val.indexOf('Luong cao') >= 0) {\n            const aMax = parseInt(a.getAttribute('data-sal-max') || '0');\n            const bMax = parseInt(b.getAttribute('data-sal-max') || '0');\n            return bMax - aMax;\n          }\n          if (val.indexOf('Ph� h?p') >= 0 || val.indexOf('Phu hop') >= 0) {\n            const aMatch = parseInt(((a.textContent || '').match(/�? kh?p:\\s*(\\d+)%/) || [])[1] || '0');\n            const bMatch = parseInt(((b.textContent || '').match(/�? kh?p:\\s*(\\d+)%/) || [])[1] || '0');\n            return bMatch - aMatch;\n          }\n          return 0;\n        });\n        sortedCards.forEach(card => grid.appendChild(card));\n      });\n    }\n  });";

